class Project(TypedDict):
    """Project, as the API answers it. See https://www.gpt-video.com/developers/objects#project"""

    id: str
    """The project id. It starts with prj_."""
    kind: Literal["autoclip", "splitscreen", "faketext", "redditstory", "streamer", "vibeedit"] | str
    """The kind of project: autoclip finds clips in a long video, splitscreen, streamer and redditstory build one video, faketext shows a chat story, vibeedit is an edit of a video. Each kind has its own operations; projects made in the GPT-Video app are listed too."""
    title: str
    """The name of the project."""
    status: Literal["draft", "processing", "ready", "failed"] | str
    """draft has not been analyzed yet, processing is being analyzed, ready has clips, failed means the last analysis failed and errorMessage says why."""
    sourceAssetId: str | None
    """The video the project is made from: the source of an Auto Clip, streamer or Vibe Editing project, the main video of a split screen project. null for Reddit story and fake text projects, whose background video is in their block, until an Auto Clip project has a source, and when the file no longer exists or cannot be used through the API."""
    compositionId: str | None
    """The composition of a split screen, streamer, Reddit story, fake text or Vibe Editing project, to export with create_export. null for an Auto Clip project, whose compositions belong to its accepted clips, and for a project that has no composition yet."""
    settings: ProjectSettings | None
    """The settings of an Auto Clip project; null for every other kind."""
    missingSettings: list[Literal["objective", "language", "clipCount", "minDurationSec", "maxDurationSec", "captionStyle", "reframe"] | str]
    """The settings still to choose before the project can be analyzed. Empty when nothing is missing, and for every kind other than autoclip."""
    splitScreen: ProjectSplitScreen | None
    """The choices of a split screen project; null for every other kind."""
    streamer: ProjectStreamer | None
    """The choices of a streamer project; null for every other kind."""
    redditStory: ProjectRedditStory | None
    """The post, the voice and the choices of a Reddit story project; null for every other kind."""
    fakeText: ProjectFakeText | None
    """The choices of a fake text project; null for every other kind."""
    vibeEdit: ProjectVibeEdit | None
    """The choices of a Vibe Editing project; null for every other kind."""
    errorMessage: str | None
    """Why the last analysis failed, in one sentence; null unless the status is failed."""
    createdAt: str
    """An ISO 8601 time in UTC."""
    updatedAt: str
    """An ISO 8601 time in UTC."""


class Job(TypedDict):
    """Job, as the API answers it. See https://www.gpt-video.com/developers/objects#job"""

    id: str
    """The job id. It starts with job_."""
    kind: Literal["analysis", "build", "export", "framing", "import", "story", "voices", "tool", "assistant_turn"] | str
    """What the job does. analysis finds the clips of an Auto Clip project, or prepares a Vibe Editing project. build makes the video of a split screen, streamer or Reddit story project. export renders a composition to a file. framing follows the face in a clip. import brings in a video from a link. story writes the story of a fake text project. voices makes the voices of a fake text story. tool runs a voiceover, an audio separation or a brainstorm. assistant_turn is one turn of the Editor Assistant."""
    status: Literal["queued", "running", "done", "failed", "cancelled"] | str
    """queued and running are still working; done, failed and cancelled are final."""
    progress: float
    """How far the job is, from 0 to 1."""
    errorMessage: str | None
    """Why the job failed or stopped, in one sentence; null otherwise."""
    projectId: str | None
    """The project the job works on, when it has one."""
    compositionId: str | None
    """The composition the job works on, when it has one."""
    exportId: str | None
    """The export this job renders, for an export job; null otherwise."""
    assetId: str | None
    """The video an import job brought in, once the job is done; null for every other job, and when that video no longer exists or cannot be used through the API."""
    toolRunId: str | None
    """The tool run a tool job carries out, to read with get_tool_run; null for every other job."""
    turnId: str | None
    """The Editor Assistant turn an assistant_turn job carries out, to read with get_assistant_turn; null for every other job."""
    createdAt: str
    """An ISO 8601 time in UTC."""
    startedAt: str | None
    """An ISO 8601 time in UTC."""
    finishedAt: str | None
    """An ISO 8601 time in UTC."""


