class Clip(TypedDict):
    """Clip, as the API answers it. See https://www.gpt-video.com/developers/objects#clip"""

    id: str
    """The clip id. It starts with cnd_."""
    projectId: str
    """The project the clip was found in."""
    sourceAssetId: str
    """The source video the clip is cut from."""
    status: Literal["proposed", "accepted", "rejected"] | str
    """proposed is waiting for a decision, accepted has a composition, rejected was set aside and can be restored."""
    rank: int
    """The place of the clip in the project, from 0, in the order the analysis ranked the clips. A new analysis puts the accepted clips it keeps first."""
    startSec: float
    """Where the clip starts in the source video, in seconds."""
    endSec: float
    """Where the clip ends in the source video, in seconds."""
    durationSec: float
    """How long the clip is, in seconds."""
    title: str
    """A short title for the clip."""
    hook: str
    """What the first seconds of the clip promise the viewer."""
    summary: str
    """What the clip is about, in a sentence or two."""
    reason: str
    """Why this moment was picked."""
    score: float
    """A priority score from 0 to 100, explained factor by factor in scoreBreakdown. It ranks the clips of a project against each other; it is not a probability of going viral."""
    scoreBreakdown: list[ClipScoreBreakdownItem]
    """One entry per factor of the score. Factors are added over time, so an older clip can have fewer entries: read each entry by its factor, never by its position."""
    tags: list[str]
    """Topics of the clip."""
    transcriptExcerpt: str
    """What is said in the clip, taken from the transcript."""
    social: ClipSocial
    """A suggested title, caption and hashtags for posting the clip."""
