    def paginate(
        self,
        operation: PaginatedOperation,
        params: Mapping[str, Any] | None = None,
        /,
        *,
        timeout: float | None = None,
        deadline: float | None = None,
        max_retries: int | None = None,
        cancel: Event | None = None,
        **fields: Any,
    ) -> Iterator[Any]:
        """Every item of a list, page after page, asking for each page only when the items of the one before are used up. operation is the id of a list, such as list_projects; the fields of the list go in params or as keyword arguments, and a cursor is where the iteration starts.

        Each page is one call with its own retries, sent with the options given here. A cursor the API sent before stops the iteration with BAD_RESPONSE, because the list would never end. A CONFLICT of list_clips reaches the caller as it is: reading on would skip or repeat clips.
        """
